package dev.eugheist.ttmodern;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
final class PlacementMirrorAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT placement mirror: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var origin=new BlockPos(5,290,5);for(int size:new int[]{3,5,7,9,11})for(var side:Direction.values()){var pattern=PlacementMirrorPattern.positions(origin,side,size,0,80);check(pattern.size()==size*size&&new java.util.HashSet<>(pattern).size()==size*size,"original odd square area all faces "+size+side);if(side.getAxis()==Direction.Axis.Y)check(pattern.stream().allMatch(p->p.getY()==origin.getY()+side.getStepY()),"downward look floor/ceiling plane");else check(pattern.stream().mapToInt(BlockPos::getY).min().orElseThrow()==290&&pattern.stream().mapToInt(BlockPos::getY).max().orElseThrow()==290+size-1,"wall rises upward from clicked height");}var yaw0=PlacementMirrorPattern.positions(origin,Direction.UP,3,0,75);var yaw90=PlacementMirrorPattern.positions(origin,Direction.UP,3,90,75);check(yaw0.stream().allMatch(p->p.getZ()==5)&&yaw90.stream().allMatch(p->p.getX()==5)&&yaw0.stream().mapToInt(BlockPos::getY).max().orElseThrow()==293,"pitch75 keeps yaw-oriented vertical plane");var level=server.overworld();var player=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"PlacementMirrorAudit"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(5,290,5);var mirror=new ItemStack(PlacementMirror.ITEM.get());PlacementMirror.bind(mirror,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());var pattern=PlacementMirrorPattern.positions(origin,Direction.UP,3,0,80);var saved=new java.util.HashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();for(var pos:pattern){saved.put(pos,level.getBlockState(pos));level.setBlockAndUpdate(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());}try{player.getInventory().setItem(9,new ItemStack(Items.STONE,8));check(PlacementMirror.place(mirror,player,pattern)==0&&pattern.stream().allMatch(p->level.getBlockState(p).isAir())&&player.getInventory().getItem(9).getCount()==8,"insufficient whole pattern leaves world and stock untouched");var talisman=new ItemStack(BlockTalisman.ITEM.get());BlockTalisman.bind(talisman,net.minecraft.world.level.block.Blocks.STONE);BlockTalisman.count(talisman,2);player.getInventory().setItem(10,talisman);check(PlacementMirror.place(mirror,player,pattern)==9&&player.getInventory().getItem(9).isEmpty()&&BlockTalisman.count(talisman)==1&&pattern.stream().allMatch(p->level.getBlockState(p).is(net.minecraft.world.level.block.Blocks.STONE)),"mixed stock inventory first then talisman,exact9 placed");for(var pos:pattern)level.setBlockAndUpdate(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());BlockTalisman.count(talisman,9);java.util.function.Consumer<net.neoforged.neoforge.event.level.BlockEvent.EntityPlaceEvent> deny=e->{if(pattern.contains(e.getPos()))e.setCanceled(true);};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(deny);try{check(PlacementMirror.place(mirror,player,pattern)==0&&BlockTalisman.count(talisman)==9&&pattern.stream().allMatch(p->level.getBlockState(p).isAir()),"all native placement cancellations roll back without reserve loss");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(deny);}player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);check(PlacementMirror.place(mirror,player,pattern)==9&&BlockTalisman.count(talisman)==9,"creative placement does not consume");var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("PLACEMENT_MIRROR")).findFirst().orElseThrow();check(recipe.componentStacks().size()==6&&recipe.componentStacks().get(1).is(Items.DROPPER)&&recipe.componentStacks().get(3).is(Items.GLASS)&&recipe.componentStacks().get(4).is(Items.BLAZE_POWDER),"original six-component recipe");System.out.println("TT PLACEMENT MIRROR AUDIT: ALL PASS (five sizes/six faces,yaw/pitch75/upward walls,whole-pattern stock gate,mixed stock order,9native blocks,cancel rollback,creative,recipe)");}finally{saved.forEach(level::setBlockAndUpdate);}}
}
